class InsufficientFunds(Exception):      # custom error for our business rule
    pass

class Account:
    rate = 0.01
    def __init__(self, owner, balance=0):
        self.owner, self.balance = owner, balance
    def withdraw(self, amount):
        if amount > self.balance:
            raise InsufficientFunds(f"{self.owner} needs {amount - self.balance} more")
        self.balance -= amount
    def describe(self):
        return f"{self.owner}: {self.balance}"

class Savings(Account):
    rate = 0.05                          # override the base default
    def __init__(self, owner, balance=0):
        super().__init__(owner, balance)  # أولاً نهيّئ سمات الأب ثم نضيف سماتنا
        self.bonus = 10
    def describe(self):
        return super().describe() + f" (rate {self.rate})"

for acc in [Account("Ali", 50), Savings("Sara", 200)]:
    print(acc.describe())                # polymorphism: same call, different result

ali = Account("Ali", 50)
for amount in (30, 500, "ten"):
    try:
        ali.withdraw(amount)
        print("ok, balance", ali.balance)
    except InsufficientFunds as e:       # specific handlers, not a bare except
        print("custom:", e)
    except TypeError:
        print("bad amount type")

