import hashlib

def sha(data):
    return hashlib.sha256(data).hexdigest()

content = b"year,temp\n2020,31\n2021,33\n"
sip = {"object": content, "metadata": {"title": "Temperatures", "creator": "Dept X"}}

# الـ PDI هو ما يحوّل SIP إلى AIP: بصمة وأصل وإحالة ثابتة
def ingest(sip, agent):
    pdi = {
        "fixity": {"sha256": sha(sip["object"])},
        "provenance": {"ingested_by": agent, "received_as": "SIP"},
        "reference": "aip-0001",
    }
    return {**sip, "pdi": pdi, "packaging": ["object", "metadata", "pdi"]}

def verify(aip):
    return sha(aip["object"]) == aip["pdi"]["fixity"]["sha256"]

aip = ingest(sip, "archive-bot")
print("SIP parts:", sorted(sip))
print("AIP parts:", sorted(aip))
print("fixity prefix:", aip["pdi"]["fixity"]["sha256"][:12])
print("fixity ok at ingest:", verify(aip))

# تغيير رقم واحد يكفي لتغيّر البصمة، وهكذا نكتشف العبث
aip["object"] = content.replace(b"33", b"34")
print("fixity ok after silent edit:", verify(aip))

