# كل وجهة نظر تسأل سؤالاً مختلفاً عن البيانات نفسها
def perspectives(it):
    name, until, documented, obsolete, reuse = it
    return {"library": reuse > 0, "records": until >= CURRENT_YEAR, "curation": documented and reuse > 0}

def decide(it):
    p = perspectives(it)
    name, until, documented, obsolete, reuse = it
    if p["records"]:
        return "keep: legal retention"
    if reuse > 0 and not documented:
        return "document context first"  # قيمة البيانات تضيع بلا سياق
    if reuse > 0 and obsolete:
        return "migrate, then keep"
    if reuse > 0:
        return "keep active"
    return "dispose"

for it in items:
    p = perspectives(it)
    flags = "".join("Y" if p[k] else "-" for k in ("library", "records", "curation"))
    print(f"{it[0]:17} L/R/C={flags}  {decide(it)}")

