LEVELS = {"low": 1, "moderate": 2, "high": 3}

def rate(life_at_risk, loss_usd, ops_halted):
    # العالي: كارثة أو خسارة أرواح. المتوسط: ضرر جسيم بلا وفيات
    if life_at_risk or loss_usd >= 5_000_000:
        return "high"
    if loss_usd >= 100_000 or ops_halted:
        return "moderate"
    return "low"

