def rbac(user, action):
    # الصلاحية تُمنح للدور لا للشخص: تغيير الوظيفة = تغيير الدور فقط
    return any(action in ROLE_PERMS[r] for r in USER_ROLES.get(user, ()))

def abac(subject, action, resource, env):
    # ABAC: سياسة واحدة تجمع سمات الذات والمورد والبيئة
    return (action == "write_grades"
            and subject["role"] == "instructor"
            and resource["course"] in subject["courses"]
            and 8 <= env["hour"] < 18)

