def laplace(scale):
    # ضجيج لابلاس = الفرق بين متغيّرين أسّيين مستقلين
    return random.expovariate(1 / scale) - random.expovariate(1 / scale)

def dp_total(names, epsilon, sensitivity=10000):
    # epsilon صغير = خصوصية أقوى = ضجيج أكبر
    return total(names) + laplace(sensitivity / epsilon)

for eps in (0.1, 1.0, 10.0):
    guess = dp_total(everyone, eps) - dp_total(others, eps)
    print(f"epsilon={eps}: attacker guess = {guess:.0f}")

