import numpy as np

rng = np.random.default_rng(42)
x0 = rng.normal(0, 1, (256, 100))

def final_std(init, act, layers=10, n=100):
    a = x0
    for _ in range(layers):
        if init == "naive":
            W = rng.normal(0, 0.01, (n, n))
        elif init == "glorot":
            W = rng.normal(0, np.sqrt(2 / (n + n)), (n, n))   # للـ tanh/sigmoid
        else:
            W = rng.normal(0, np.sqrt(2 / n), (n, n))         # He: للـ ReLU
        a = act(a @ W)
    return float(a.std())

relu = lambda z: np.maximum(0, z)
# التهيئة الصغيرة تُميت الإشارة، والمناسبة للتنشيط تُبقي تباينها قريباً من ثابت
print("naive  + tanh:", f"{final_std('naive', np.tanh):.0e}")
print("glorot + tanh:", round(final_std("glorot", np.tanh), 2))
print("naive  + relu:", f"{final_std('naive', relu):.0e}")
print("he     + relu:", round(final_std("he", relu), 2))

class Var:
    """قيمة تسجّل العمليات التي أنتجتها (مثل GradientTape) لنحسب التدرج عكسياً."""
    def __init__(self, v, parents=()):
        self.v, self.g, self.parents = v, 0.0, parents
    def __add__(self, o):
        o = o if isinstance(o, Var) else Var(o)
        return Var(self.v + o.v, ((self, 1.0), (o, 1.0)))
    def __mul__(self, o):
        o = o if isinstance(o, Var) else Var(o)
        return Var(self.v * o.v, ((self, o.v), (o, self.v)))
    __radd__, __rmul__ = __add__, __mul__
    def backward(self):
        order, seen = [], set()
        def visit(n):
            if id(n) not in seen:
                seen.add(id(n))
                for p, _ in n.parents: visit(p)
                order.append(n)
        visit(self); self.g = 1.0
        for n in reversed(order):
            for p, local in n.parents: p.g += local * n.g

xs, ys = [0.0, 1.0, 2.0, 3.0], [1.0, 3.0, 5.0, 7.0]   # y = 2x + 1
w, b, lr = Var(0.0), Var(0.0), 0.05
for step in range(200):
    w.g = b.g = 0.0
    loss = Var(0.0)
    for x, y in zip(xs, ys):
        err = w * x + b + (-y)               # 1) تمرير أمامي
        loss = loss + err * err * (1 / 4)    # 2) خسارة MSE
    loss.backward()                          # 3) التدرجات بالتفاضل التلقائي
    if step == 0: print("first grads:", round(w.g, 2), round(b.g, 2))
    w.v -= lr * w.g; b.v -= lr * b.g         # 4) تحديث الأوزان
print("learned w, b:", round(w.v, 2), round(b.v, 2), "| loss:", round(loss.v, 4))

import random

class Dataset:
    """محاكاة مبسطة لـ tf.data.Dataset: كل تحويل يرجع مجموعة جديدة فيمكن تسلسلها."""
    def __init__(self, items): self.items = list(items)
    @staticmethod
    def from_tensor_slices(data): return Dataset(data)   # يقطّع على البعد الأول
    def map(self, fn): return Dataset(fn(x) for x in self.items)
    def shuffle(self, seed):
        items = self.items[:]; random.Random(seed).shuffle(items); return Dataset(items)
    def batch(self, n):
        return Dataset(self.items[i:i + n] for i in range(0, len(self.items), n))
    def __iter__(self): return iter(self.items)

base = Dataset.from_tensor_slices(range(1, 7))

# map ثم batch: الدالة تطبَّق على كل عنصر على حدة
print("map->batch :", list(base.map(lambda x: x * 10).batch(3)))
# batch ثم map: الدالة تطبَّق على الدفعة كلها، فالترتيب غيّر معنى الدالة
print("batch->map :", list(base.batch(3).map(lambda b: sum(b))))

# الخلط قبل التجميع يوزع العناصر على الدفعات؛ بعده يخلط الدفعات كاملةً فقط
print("shuffle->batch:", list(base.shuffle(seed=1).batch(3)))
print("batch->shuffle:", list(base.batch(3).shuffle(seed=1)))

