def sheet(group_by, region=None):
    # إجراء التصفية: القيمة المحددة في ورقة تصبح مرشّحاً في الورقة الأخرى
    totals = {}
    for r, cat, amount in orders:
        if region and r != region:
            continue
        key = r if group_by == "region" else cat
        totals[key] = totals.get(key, 0) + amount
    return dict(sorted(totals.items(), key=lambda kv: -kv[1]))

