import numpy as np

# وادٍ ضيّق: انحدار شديد في y وخفيف في x، وهذا يُبطئ SGD العادي
grad = lambda p: np.array([p[0], 25.0 * p[1]])
loss = lambda p: 0.5 * (p[0] ** 2 + 25.0 * p[1] ** 2)
start = np.array([5.0, 1.0])

def run(method, steps=60, lr=0.05):
    p, m, v = start.copy(), np.zeros(2), np.zeros(2)
    for t in range(1, steps + 1):
        g = grad(p)
        if method == "sgd":
            p = p - lr * g
        elif method == "momentum":
            m = 0.9 * m + g              # الزخم يجمع الاتجاه المتكرر فيسرّع الحركة
            p = p - lr * m
        else:
            m = 0.9 * m + 0.1 * g
            v = 0.999 * v + 0.001 * g * g
            p = p - 0.3 * (m / (1 - 0.9 ** t)) / (np.sqrt(v / (1 - 0.999 ** t)) + 1e-8)
    return loss(p)

for name in ("sgd", "momentum", "adam"):
    print(f"{name:>8}: final loss = {run(name):.4f}")

import numpy as np

corpus = ["cat chases mouse", "dog chases cat", "cat drinks milk", "dog drinks water",
          "car needs fuel", "car needs repair", "truck needs fuel", "truck needs repair"]
words = sorted({w for s in corpus for w in s.split()})
idx = {w: i for i, w in enumerate(words)}
M = np.zeros((len(words), len(words)))
for s in corpus:
    toks = s.split()
    for i, w in enumerate(toks):
        for j, c in enumerate(toks):
            if i != j:
                M[idx[w], idx[c]] += 1          # السياق = بقية كلمات الجملة

