pw, pc = M.sum(1, keepdims=True) / total, M.sum(0, keepdims=True) / total
with np.errstate(divide="ignore"):
    ppmi = np.maximum(np.log2((M / total) / (pw * pc)), 0)

def cos(u, v):
    # الجيب يقيس الزاوية فقط فلا يتأثر بطول المتجه
    return u @ v / (np.linalg.norm(u) * np.linalg.norm(v))

