import math, random

vocab = ["the", "a", "cat", "dog", "pizza", "quantum"]
logits = [3.0, 2.2, 2.0, 1.5, 0.5, -1.0]

def softmax(z, T=1.0):
    e = [math.exp(x / T) for x in z]            # T صغيرة تحدّ التوزيع، وT كبيرة تسطّحه
    s = sum(e)
    return [x / s for x in e]

def keep_only(p, keep):
    q = [x if i in keep else 0.0 for i, x in enumerate(p)]
    s = sum(q)
    return [x / s for x in q]                   # نعيد التطبيع بعد القص

def top_k(p, k):
    order = sorted(range(len(p)), key=lambda i: -p[i])
    return keep_only(p, set(order[:k]))

def top_p(p, thr):
    # Top-p يقصّ بالاحتمال التراكمي لا بعدد ثابت من الكلمات
    keep, cum = set(), 0.0
    for i in sorted(range(len(p)), key=lambda i: -p[i]):
        keep.add(i); cum += p[i]
        if cum >= thr:
            break
    return keep_only(p, keep)

base = softmax(logits)
dists = {"T=1.0": base, "T=0.5": softmax(logits, 0.5), "T=2.0": softmax(logits, 2.0),
         "top-k=2": top_k(base, 2), "top-p=0.9": top_p(base, 0.9)}
