tags = ["DET", "PRON", "AUX", "NOUN", "VERB"]
start = {"DET": 0.3, "PRON": 0.4, "AUX": 0.05, "NOUN": 0.2, "VERB": 0.05}
trans = {"DET": {"DET": 0.04, "PRON": 0.02, "AUX": 0.02, "NOUN": 0.9, "VERB": 0.02},
         "PRON": {"DET": 0.04, "PRON": 0.02, "AUX": 0.48, "NOUN": 0.08, "VERB": 0.38},
         "AUX": {"DET": 0.12, "PRON": 0.05, "AUX": 0.03, "NOUN": 0.2, "VERB": 0.6},
         "NOUN": {"DET": 0.05, "PRON": 0.05, "AUX": 0.3, "NOUN": 0.1, "VERB": 0.5},
         "VERB": {"DET": 0.4, "PRON": 0.15, "AUX": 0.05, "NOUN": 0.3, "VERB": 0.1}}
emit = {"DET": {"the": 1.0}, "PRON": {"she": 0.5, "they": 0.5}, "AUX": {"can": 0.8, "will": 0.2},
        "NOUN": {"can": 0.05, "fish": 0.4}, "VERB": {"can": 0.02, "fish": 0.3}}

def viterbi(words):
    # best[t][tag] = أعلى احتمال لمسار ينتهي بهذا الوسم عند الكلمة t
    best = [{t: (start[t] * emit[t].get(words[0], 0), None) for t in tags}]
    for w in words[1:]:
        prev, row = best[-1], {}
        for t in tags:
            # نحتفظ بأفضل سابق فقط بدل تجربة كل المسارات (برمجة ديناميكية)
            p, back = max((prev[s][0] * trans[s][t], s) for s in tags)
            row[t] = (p * emit[t].get(w, 0), back)
        best.append(row)
    tag = max(tags, key=lambda t: best[-1][t][0])
    prob, path = best[-1][tag][0], [tag]
    for row in reversed(best[1:]):
        path.append(row[path[-1]][1])
    return path[::-1], prob

for sent in ["she can fish", "the fish can"]:
    path, prob = viterbi(sent.split())
    print(sent, "->", " ".join(path), f"(p={prob:.2e})")

from collections import defaultdict

lexicon = {"the": ["Det"], "man": ["N"], "dog": ["N"], "telescope": ["N"],
           "saw": ["V"], "with": ["P"]}
# كل قاعدة ثنائية (B, C) لأن CKY يشترط صيغة تشومسكي الطبيعية
rules = {("NP", "VP"): ["S"], ("V", "NP"): ["VP"], ("VP", "PP"): ["VP"],
         ("Det", "N"): ["NP"], ("NP", "PP"): ["NP"], ("P", "NP"): ["PP"]}

def count_parses(words):
    n = len(words)
    chart = [[defaultdict(int) for _ in range(n + 1)] for _ in range(n + 1)]
    for i, w in enumerate(words):
        for A in lexicon.get(w, []):
            chart[i][i + 1][A] += 1
    for span in range(2, n + 1):
        for i in range(n - span + 1):
            j = i + span
            for k in range(i + 1, j):          # نقطة الانقسام: نعيد استعمال خلايا أصغر
                for B, nb in chart[i][k].items():
                    for C, nc in chart[k][j].items():
                        for A in rules.get((B, C), []):
                            chart[i][j][A] += nb * nc
    return chart[0][n]["S"]

for s in ["the man saw the dog", "the man saw the dog with the telescope",
          "saw the man the"]:
