def tlv(tag, body):
    return bytes([tag, len(body)]) + body        # طول أقل من 128 فقط في هذا المثال

def enc_int(n):
    size = (n.bit_length() + 8) // 8            # نحجز بتّاً للإشارة
    return tlv(0x02, n.to_bytes(size, "big", signed=True))

def enc_str(s):
    return tlv(0x04, s.encode())

def enc_oid(dotted):
    a = [int(x) for x in dotted.split(".")]
    body = bytes([a[0] * 40 + a[1]])            # أول رقمين يُدمجان في بايت واحد
    for n in a[2:]:
        chunk = [n & 0x7F]
        n >>= 7
        while n:
            chunk.insert(0, 0x80 | (n & 0x7F))
            n >>= 7
        body += bytes(chunk)
    return tlv(0x06, body)

