links = {"A": "BC", "B": "AD", "C": "AD", "D": "BCE", "E": "DF", "F": "E"}

def worm(start, blocked=()):
    # الدودة تنسخ نفسها لكل جار بلا تدخّل بشري
    seen, queue = {start}, deque(start)
    while queue:
        host = queue.popleft()
        for peer in links[host]:
            cut = (host, peer) in blocked or (peer, host) in blocked
            if peer not in seen and not cut:
                seen.add(peer)
                queue.append(peer)
    return "".join(sorted(seen))

