N = 40
def neighbors(i):                # شبكة بسيطة: كل جهاز يصل إلى جيرانه القريبين
    return {(i + 1) % N, (i - 1) % N, (i + 5) % N, (i - 5) % N}

def outbreak(patched):
    infected, frontier, rounds = {1}, {1}, 0
    while frontier:
        nxt = set()
        for host in frontier:
            for nb in neighbors(host):
                # الدودة تصيب فقط الأجهزة غير المرقّعة، وبلا نقرة من أحد
                if nb not in infected and nb not in patched:
                    nxt.add(nb)
        infected |= nxt
        frontier = nxt
        rounds += 1 if nxt else 0
    return len(infected), rounds

