N, E0, HEADS = 10, 1000, 2
CH_COST, MEMBER_COST = 50, 10            # الرأس يجمع ويرسل فيستهلك أضعاف العضو

def first_death(rotate):
    energy = [E0] * N
    for rnd in range(1, 1000):
        # التدوير: يتولّى الدور الأعلى طاقةً الآن؛ الثابت: العقدتان 0 و1 دائمًا
        order = sorted(range(N), key=lambda i: (-energy[i], i)) if rotate else list(range(N))
        heads = set(order[:HEADS])
        for i in range(N):
            energy[i] -= CH_COST if i in heads else MEMBER_COST
        if min(energy) <= 0:
            return rnd, max(energy) - min(energy)

