def linear(a, t):
    for i, x in enumerate(a):
        if x == t:
            return i, i + 1
    return -1, len(a)

def binary(a, t, trace=False):
    lo, hi, probes = 0, len(a) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        probes += 1
        if trace:
            print(f"  lo={lo} hi={hi} mid={mid} a[mid]={a[mid]}")
        if a[mid] == t:
            return mid, probes
        # القائمة مرتّبة، فنتخلص من نصف المجال في كل خطوة
        if a[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, probes

