def bubble(a):
    a, c = a[:], 0
    for i in range(len(a) - 1):
        swapped = False
        for j in range(len(a) - 1 - i):
            c += 1
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped: break    # مرّة بلا تبديل = القائمة مرتّبة فنتوقف
    return a, c
def selection(a):
    a, c = a[:], 0
    for i in range(len(a) - 1):
        m = i
        for j in range(i + 1, len(a)):
            c += 1
            if a[j] < a[m]:
                m = j
        a[i], a[m] = a[m], a[i]
    return a, c
def insertion(a):
    a, c = a[:], 0
    for i in range(1, len(a)):
        key, j = a[i], i - 1
        while j >= 0:
            c += 1
            if a[j] <= key: break
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a, c
