def merge(left, right):
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:  # <= تحافظ على ترتيب المتساويين (ثبات الفرز)
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
    return out + left[i:] + right[j:]

def merge_sort(xs, depth=0):
    pad = "  " * depth
    if len(xs) <= 1:
        return xs
    mid = len(xs) // 2
    print(f"{pad}split {xs} -> {xs[:mid]} | {xs[mid:]}")
    merged = merge(merge_sort(xs[:mid], depth + 1), merge_sort(xs[mid:], depth + 1))
    print(f"{pad}merge -> {merged}")
    return merged

