def bsearch(a, target, lo, hi, depth=0):
    pad = "  " * depth
    if lo > hi:  # المجال فارغ: القيمة غير موجودة
        print(f"{pad}lo={lo} hi={hi} -> empty range")
        return -1
    mid = (lo + hi) // 2
    print(f"{pad}lo={lo} hi={hi} mid={mid} a[mid]={a[mid]}")
    if a[mid] == target:
        return mid
    if a[mid] < target:
        return bsearch(a, target, mid + 1, hi, depth + 1)
    return bsearch(a, target, lo, mid - 1, depth + 1)

