from math import log2

def T(n, a, b, d):
    t = 1  # T(1) = 1
    m = 1
    while m < n:
        m *= b
        t = a * t + m ** d  # T(m) = a T(m/b) + m^d
    return t

def growth(n, a, b, d):  # الحالات الثلاث: a مقابل b^d
    if a < b ** d:
        return "n^d", n ** d
    if a == b ** d:
        return "n^d log n", n ** d * log2(n)
    return "n^(log_b a)", n ** (log2(a) / log2(b))

