from functools import reduce

class Node:
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.key:  # الأصغر يميل يساراً والأكبر يميناً
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def search(root, key):
    path = []
    while root:
        path.append(root.key)
        if key == root.key:
            return True, path
        root = root.left if key < root.key else root.right
    return False, path

def inorder(r):
    return inorder(r.left) + [r.key] + inorder(r.right) if r else []

def height(r):
    return 1 + max(height(r.left), height(r.right)) if r else 0

build = lambda keys: reduce(insert, keys, None)

