from math import ceil, log2, factorial

def binary_insertion(items):
    arr, path = [], []
    for x in items:
        lo, hi = 0, len(arr)
        while lo < hi:
            mid = (lo + hi) // 2
            went_left = x < arr[mid]  # كل مقارنة عقدة، ونتيجتها الفرع المسلوك
            path.append(went_left)
            if went_left:
                hi = mid
            else:
                lo = mid + 1
        arr.insert(lo, x)
    return arr, tuple(path)

for n in (3, 4, 5):
    leaves, worst = set(), 0
    for perm in permutations(range(n)):
        arr, path = binary_insertion(perm)
        assert arr == sorted(perm)
        leaves.add(path)
        worst = max(worst, len(path))
    bound = ceil(log2(factorial(n)))
    print(f"n={n}: {factorial(n):3d} orderings -> {len(leaves):3d} distinct leaves, "
          f"worst depth {worst}, lower bound {bound}")

