import numpy as np

def is_spanning_tree(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # دورة: ليست شجرة
        parent[ra] = rb
    return True  # n-1 حافة بلا دورة تعني متصلة، أي شجرة ممتدة

def laplacian_count(n, edges):
    L = np.zeros((n, n))
    for a, b in edges:
        L[a, a] += 1
        L[b, b] += 1
        L[a, b] -= 1
        L[b, a] -= 1
    return round(np.linalg.det(L[1:, 1:]))

