def ends(node, s, i):
    kind = node[0]
    if kind == "lit":
        return {i + 1} if s[i:i + 1] == node[1] else set()
    if kind == "alt":
        return ends(node[1], s, i) | ends(node[2], s, i)
    if kind == "cat":
        return {k for j in ends(node[1], s, i) for k in ends(node[2], s, j)}
    reach, frontier = {i}, {i}  # النجمة: نكرّر المطابقة حتى لا تظهر مواضع جديدة
    while frontier:
        frontier = {j for p in frontier for j in ends(node[1], s, p)} - reach
        reach |= frontier
    return reach

def recognizes(node, s):
    return len(s) in ends(node, s, 0)

