def p_always(x):
    return
    yield

def p_even_loops(x):
    while x % 2 == 0:  # يدور للأبد إن كان الدخل زوجياً
        yield

def p_countdown(x):
    while x > 0:
        x -= 1
        yield

def p_collatz(x):
    while x != 1:
        x = x // 2 if x % 2 == 0 else 3 * x + 1
