def nums(n):
    return [(7 * i + 3) % 23 + 4 for i in range(n)]

def verify(items, mask, target):
    # التحقق من الشهادة: مرور واحد على n عنصراً (كثير حدود)
    chosen = [x for i, x in enumerate(items) if mask >> i & 1]
    return sum(chosen) == target, len(items)

def search(items, target):
    for tried, mask in enumerate(range(2 ** len(items)), start=1):
        if verify(items, mask, target)[0]:
            return mask, tried
    return None, 2 ** len(items)  # البحث الشامل أُسّي

print(" n  verify-ops  search(solvable)  search(impossible)")
for n in (8, 12, 16):
    items = nums(n)
    target = sum(items[1::3])
    mask, tried = search(items, target)
    _, nope = search(items, sum(items) + 1)
    ok, ops = verify(items, mask, target)
    print(f"{n:2d}  {ops:10d}  {tried:16d}  {nope:18d}  certificate ok={ok}")

class Link:
    def __init__(self, mode):
        self.mode, self.turn = mode, "A->B"

    def grant(self, wants):
        if self.mode == "simplex":
            return [d for d in wants if d == "A->B"]       # one fixed direction
        if self.mode == "half-duplex":
            pick = self.turn if self.turn in wants else wants[0]
            # نصف المزدوج: يتناوب الطرفان على قناةٍ واحدة
            self.turn = "B->A" if pick == "A->B" else "A->B"
            return [pick]
        return list(wants)                                 # full duplex: both at once

for mode in ("simplex", "half-duplex", "full-duplex"):
    link, total = Link(mode), 0
    print(mode)
    for slot in range(1, 5):
        wants = ["A->B", "B->A"]          # both stations always have data
        ok = link.grant(wants)
        total += len(ok)
        blocked = [d for d in wants if d not in ok]
        print(f"  slot {slot}: sent {ok} blocked {blocked}")
    print("  delivered in 4 slots:", total)

