    "ring": [(i, (i + 1) % N) for i in range(N)],
    "star": [(0, i) for i in range(1, N)],            # station 0 plays the hub
    "mesh": list(combinations(stations, 2)),
}

def largest_group(links):
    seen, best = set(), 0
    for s in stations:
        if s in seen:
            continue
        stack, group = [s], {s}
        while stack:
            u = stack.pop()
            for a, b in links:
                v = b if a == u else a if b == u else None
                if v is not None and v not in group:
                    group.add(v)
                    stack.append(v)
        seen |= group
        best = max(best, len(group))
    return best

