def shortest_path(src, dst):
    graph = {}
    for a, b in links:
        graph.setdefault(a, []).append(b)
        graph.setdefault(b, []).append(a)
    prev, queue = {src: None}, deque([src])
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if nxt not in prev:
                prev[nxt] = node
                queue.append(nxt)
    path, node = [], dst
    while node:
        path.append(node)
        node = prev[node]
    return path[::-1]

