class Transport:                      # splits text into numbered 4-char segments
    def down(self, text):
        return [f"{i}:{text[i:i + 4]}" for i in range(0, len(text), 4)]

    def up(self, parts):
        ordered = sorted(parts, key=lambda p: int(p.split(":")[0]))
        return "".join(p.split(":", 1)[1] for p in ordered)

class LinkSum:                        # link layer A: byte-sum check
    def down(self, parts):
        return [(p, sum(p.encode()) % 256) for p in parts]

    def up(self, frames):
        return [p for p, c in frames if sum(p.encode()) % 256 == c]

class LinkParity(LinkSum):            # link layer B: parity of the 1-bits
    @staticmethod
    def tag(p):
        return bin(int.from_bytes(p.encode(), "big")).count("1") % 2

    def down(self, parts):
        return [(p, self.tag(p)) for p in parts]

    def up(self, frames):
        return [p for p, c in frames if self.tag(p) == c]

def deliver(link, text):
    parts = Transport().down(text)
    frames = link.down(parts)
    print(" frames:", frames[:2], "...")
    frames = frames[::-1]             # الشبكة تعكس الترتيب والنقل يعيده
    return Transport().up(link.up(frames))

# تبديل طبقة الوصلة لا يمسّ النقل ولا التطبيق
for link in (LinkSum(), LinkParity()):
    print(type(link).__name__)
    print(" application got:", deliver(link, "layers hide detail"))

