FLAG, ESC = 0x7E, 0x7D

def frame(dst, src, payload, stuff):
    body = bytearray()
    for b in payload:
        if stuff and b in (FLAG, ESC):
            body.append(ESC)               # حشو: بايت هروب قبل كل بايت يشبه العلامة
        body.append(b)
    return bytes([FLAG, dst, src]) + bytes(body) + bytes([FLAG])

def deframe(data):
    inner, out, i = data[1:-1], bytearray(), 0
    while i < len(inner):
        if inner[i] == ESC:
            i += 1                         # skip the escape, keep the next byte literally
        out.append(inner[i])
        i += 1
    return out[0], out[1], bytes(out[2:])

