def resolve(src_ip, dst_ip):
    if dst_ip in cache[src_ip]:
        print(f"{src_ip}: cache hit {dst_ip} -> {cache[src_ip][dst_ip]} (no broadcast)")
        return
    print(f"{src_ip}: ARP request 'who has {dst_ip}?' sent to {BCAST}")
    for ip, mac in hosts.items():
        if ip == src_ip:
            continue
        if ip == dst_ip:
            # الرد أحاديّ الوجهة لأن المجيب عرف MAC السائل من الطلب نفسه
            print(f"  {ip} replies unicast to {hosts[src_ip]}: {ip} is at {mac}")
            cache[src_ip][dst_ip] = mac
            cache[ip][src_ip] = hosts[src_ip]
        else:
            print(f"  {ip} ignores the request")

