import struct, zlib

def mac(text):
    return bytes(int(x, 16) for x in text.split(":"))

def build(dst, src, ethertype, payload):
    payload = payload.ljust(46, b"\x00")             # الحد الأدنى للإطار 64 بايت بما فيها CRC
    body = mac(dst) + mac(src) + struct.pack("!H", ethertype) + payload
    return body + struct.pack("<I", zlib.crc32(body))

def fcs_ok(frame):
    return zlib.crc32(frame[:-4]) == struct.unpack("<I", frame[-4:])[0]

