def prove(facts, implications, goal):
    lines = []
    def add(text, why):
        lines.append(text)
        print(f"{len(lines):>3}. {text:<34}{why}")
    ref = {}
    for f in facts:
        add(f, "premise")
        ref[f] = len(lines)
    for a, b in implications:
        add(f"{a} -> {b}", "premise")
        ref[(a, b)] = len(lines)
    known, imps, changed = set(facts), set(implications), True
    while changed:
        changed = False
        for a, b in sorted(imps):
            if a in known and b not in known:           # الوضع: من P و P->Q نستنتج Q
                add(b, f"modus ponens {ref[a]},{ref[(a, b)]}")
                known.add(b); ref[b] = len(lines); changed = True
        for a, b in sorted(imps):
            for c, d in sorted(imps):
                if b == c and (a, d) not in imps:       # القياس الشرطي: P->Q و Q->R يعطيان P->R
                    add(f"{a} -> {d}", f"syllogism {ref[(a, b)]},{ref[(c, d)]}")
                    imps.add((a, d)); ref[(a, d)] = len(lines); changed = True
    print("goal", goal, "derived:", goal in known)

