def lang(e, n):
    """اللغة بتعريفٍ استقرائيّ على شكل التعبير، مقطوعةً عند الطول n."""
    t = e[0]
    if t == "lit":
        return {e[1]}
    if t == "or":
        return lang(e[1], n) | lang(e[2], n)
    if t == "cat":
        return {x + y for x in lang(e[1], n) for y in lang(e[2], n) if len(x + y) <= n}
    base, out = lang(e[1], n), {""}
    while True:
        bigger = out | {x + y for x in out for y in base if len(x + y) <= n}
        if bigger == out:
            return out
        out = bigger

