def classify(prods):
    nt = str.isupper                   # الحروف الكبيرة لا طرفيّات
    def right_lin(l, r):   # A -> w أو A -> wB
        return len(l) == 1 and nt(l) and not any(map(nt, r[:-1]))
    def left_lin(l, r):    # A -> w أو A -> Bw
        return len(l) == 1 and nt(l) and not any(map(nt, r[1:]))
    if all(right_lin(*p) for p in prods) or all(left_lin(*p) for p in prods):
        return "Type 3 (regular)"
    if all(len(l) == 1 and nt(l) for l, r in prods):
        return "Type 2 (context-free)"
    if all(len(l) <= len(r) for l, r in prods):
        return "Type 1 (context-sensitive)"
    return "Type 0 (unrestricted)"

