def derive(prods, maxlen):             # بحثٌ بالعرض في الصيغ الجملية بطولٍ لا يتجاوز maxlen
    seen, frontier = {"S"}, ["S"]
    while frontier:
        nxt = []
        for f in frontier:
            for l, r in prods:
                i = f.find(l)
                while i != -1:
                    g = f[:i] + r + f[i + len(l):]
                    if len(g) <= maxlen and g not in seen:
                        seen.add(g)
                        nxt.append(g)
                    i = f.find(l, i + 1)
        frontier = nxt
    return sorted((f for f in seen if f.islower()), key=lambda s: (len(s), s))
