def build(pattern, alphabet="ab"):
    """NFA للغة: كل السلاسل التي تحوي pattern. الحالة i = قرأنا i رمزاً من النمط."""
    n = len(pattern)
    d = {q: {} for q in range(n + 1)}
    for a in alphabet:
        d[0].setdefault(a, set()).add(0)          # حلقة البداية: نتجاهل ما قبل النمط
        d[n].setdefault(a, set()).add(n)          # حلقة القبول: ما بعد النمط لا يهمّ
    for i, ch in enumerate(pattern):
        d[i].setdefault(ch, set()).add(i + 1)     # خطّ النمط: هنا يتفرّع الاختيار غير الحتمي
    return d, n

def paths(d, word, trail=(0,)):
    q = trail[-1]
    if not word:
        yield trail
        return
    nxt = sorted(d[q].get(word[0], ()))
    if not nxt:
        yield trail + ("X",)                      # لا انتقال: المسار يموت
    for r in nxt:
        yield from paths(d, word[1:], trail + (r,))

