def analyse(name, T, F):
    fwd = {q: set(T[q]) for q in T}
    back = {r: {q for q in T if r in T[q]} for r in T}
    useful = closure(fwd, {0}) & closure(back, F)      # تُبلغ من البداية ومنها يُبلغ القبول
    live = {q: fwd[q] & useful for q in useful}
    infinite = any(q in closure(live, live[q]) for q in useful)   # دورة بين الحالات المفيدة
    word = separate(T, F, *EMPTY)                      # لا فرق عن الفارغة = اللغة فارغة
    print(f"{name}: empty={word is None} infinite={infinite} useful={sorted(useful)} shortest={word!r}")

