        i = form.find("S")
        if i < 0:
            out.add(form)
            continue
        for body in P["S"]:
            nxt = form[:i] + body + form[i + 1:]
            if len(nxt.replace("S", "")) <= limit and nxt not in seen:
                seen.add(nxt)
                todo.append(nxt)
    return out

