            # الطرفيّات الثابتة (قبل المتغيّر أو بعده) يجب أن تطابق الكلمة
            fixed_ok = W.startswith(nxt[:i]) if leftmost else W.endswith(nxt[i + len(body):])
            if fixed_ok and len(nxt) <= len(W) and nxt not in seen:
