def parse(sym, toks, i):
    if sym not in G:                              # ورقة: طرفيّ يطابق الكلمة الحاليّة
        if i < len(toks) and toks[i] == sym:
            yield sym, i + 1
        return
    for body in G[sym]:                           # نجرّب كلّ إنتاج، ويتراجع المحلّل عند الفشل
        for kids, j in seq(body, toks, i):
            yield (sym, kids), j

def seq(body, toks, i):
    if not body:
        yield [], i
        return
    for tree, j in parse(body[0], toks, i):
        for rest, k in seq(body[1:], toks, j):
            yield [tree] + rest, k

