# قواعد غامضة: E → E+E | E*E | a
GRAMMAR = {"E": [["E", "+", "E"], ["E", "*", "E"], ["a"]]}

def trees(sym, s, i, j):
    """كل أشجار الإعراب التي تُنتج s[i:j] انطلاقاً من sym."""
    if sym not in GRAMMAR:                  # طرفيّ: يطابق حرفاً واحداً فقط
        return [sym] if j == i + 1 and s[i] == sym else []
    return [(sym, kids) for rhs in GRAMMAR[sym] for kids in forests(rhs, s, i, j)]

def forests(rhs, s, i, j):
    """تقسيم s[i:j] على رموز الإنتاج. لا ε، فكل رمزٍ يأخذ حرفاً واحداً على الأقل."""
    if not rhs:
        return [[]] if i == j else []
    out = []
    # يجب أن يبقى حرفٌ لكل رمزٍ متبقٍّ، فلا نتجاوز j - (عدد الرموز - 1)
    for k in range(i + 1, j - len(rhs) + 2):
        for head in trees(rhs[0], s, i, k):
            for tail in forests(rhs[1:], s, k, j):
                out.append([head] + tail)
    return out

def show(t):
    if isinstance(t, str):
        return t
    sym, kids = t
    return f"{sym}[" + " ".join(show(k) for k in kids) + "]"

