import re
# E -> T ((+|-) T)* ؛ T -> F ((*|/) F)* ؛ F -> عدد | ( E ) : مستوى القاعدة هو الأولويّة
OPS = {"+": int.__add__, "-": int.__sub__, "*": int.__mul__, "/": int.__floordiv__}
def compile_expr(src):
    toks, code = re.findall(r"\d+|[-+*/()]", src) + ["$"], []     # $ حارس نهاية الإدخال
    def eat(expect=None):
        t = toks.pop(0)
        if expect and t != expect:
            raise SyntaxError(f"expected {expect}, got {t!r}")
        return t
    def level(sub, ops):
        sub()
        while toks[0] in ops:
            op = eat()
            sub()
            code.append(op)                 # المعامل بعد معاملَيه: صيغة postfix
    def factor():
        if toks[0] == "(":
            eat(), expr(), eat(")")
        elif toks[0].isdigit():
            code.append(eat())
        else:
            raise SyntaxError(f"unexpected {toks[0]!r}")
    term = lambda: level(factor, ("*", "/"))
    expr = lambda: level(term, ("+", "-"))
    expr()
    if toks != ["$"]:
        raise SyntaxError(f"trailing {toks[0]!r}")
    return code
for src in ["2+3*(4-1)", "2+*3"]:
    try:
        code = compile_expr(src)
    except SyntaxError as e:
        print(src, "-> syntax error:", e)
        continue
    print(src, "->", " ".join(code))
    stack = []
    for ins in code:
        stack.append(int(ins) if ins.isdigit() else OPS[ins](*[stack.pop(), stack.pop()][::-1]))
        print(f"  {ins:>2}  stack {stack}")

# المكدّس يعدّ الأقواس المفتوحة بلا سقف ؛ هذا ما لا تملكه الأوتوماتا المنتهية
def pda_check(s, trace=False):
    stack, deepest = [], 0
    for ch in s:
        if ch == "(":
            stack.append(ch)
        elif stack:
            stack.pop()
        else:
            return False, deepest                 # ')' بلا '(' تقابلها: المكدّس فارغ
        deepest = max(deepest, len(stack))
        if trace:
            print(f"  read {ch}  stack={''.join(stack) or 'empty'}")
    return not stack, deepest

# عدّاد محدود k=3 (أي أربع حالات): يتشبّع عند 3 فلا يميّز عمقاً 4 من عمق 3
def capped(s, k=3):
    c = 0
    for ch in s:
        c = min(c + 1, k) if ch == "(" else c - 1
        if c < 0:
            return False
    return c == 0

