# PDA = (Q, Sigma, Gamma, delta, q0, Z0, F) ؛ delta: (حالة، حرف أو eps، قمّة) -> قائمة (حالة، سلسلة تُدفع)
Q, SIGMA, GAMMA = {"q0", "q1", "q2"}, {"a", "b"}, {"Z", "A"}
DELTA = {("q0", "a", "Z"): [("q0", "AZ")], ("q0", "a", "A"): [("q0", "AA")],
         ("q0", "b", "A"): [("q1", "")], ("q1", "b", "A"): [("q1", "")],
         ("q0", "", "Z"): [("q2", "Z")], ("q1", "", "Z"): [("q2", "Z")]}
GOOD = (Q, SIGMA, GAMMA, DELTA, "q0", "Z", {"q2"})
BAD = (Q, SIGMA, GAMMA, {**DELTA, ("q0", "c", "Z"): [("q9", "BZ")]}, "q0", "Y", {"q2", "q7"})

def validate(pda):
    Q, S, G, d, q0, Z0, F = pda
    errs = set()
    errs |= {"start state not in Q"} if q0 not in Q else set()
    errs |= {"Z0 not in Gamma"} if Z0 not in G else set()
    errs |= {f"final states outside Q: {sorted(F - Q)}"} if not F <= Q else set()
    for (q, a, X), moves in d.items():
        errs |= {f"input {a!r} not in Sigma"} if a and a not in S else set()
        for p, g in moves:
            errs |= {f"target state {p} not in Q"} if p not in Q else set()
            errs |= {f"pushes {sorted(set(g) - G)} not in Gamma"} if set(g) - G else set()
    return sorted(errs)

def accepts(pda, w):
    Q, S, G, d, q0, Z0, F = pda
    todo, seen = [(q0, 0, Z0)], set()
    while todo:
        q, i, st = todo.pop()
        if (q, i, st) in seen or len(st) > 12:
            continue
        seen.add((q, i, st))
        if i == len(w) and q in F:
            return True
        for a in ["", w[i:i + 1]]:
            todo += [(p, i + len(a), g + st[1:]) for p, g in d.get((q, a, st[:1]), [])]
    return False

for name, pda in (("GOOD", GOOD), ("BAD", BAD)):
