def action(X, g):
    if g == "":
        return "pop"
    if g == X:
        return "no change"
    if len(g) > 1 and g.endswith(X):
        return f"push {g[:-1]}"
    if len(g) == 1:
        return f"replace {X} by {g}"
    return f"replace {X} by {g[-1]}, push {g[:-1]}"

