# PDA بالقبول بالحالة النهائيّة للغة a^n b^(2n) ؛ كلّ a تدفع رمزين A
D = {("q0", "a", "Z"): [("q0", "AAZ")], ("q0", "a", "A"): [("q0", "AAA")],
     ("q0", "b", "A"): [("q1", "")], ("q1", "b", "A"): [("q1", "")],
     ("q0", "", "Z"): [("q2", "Z")], ("q1", "", "Z"): [("q2", "Z")]}

def moves(idn):
    q, w, st = idn                                   # الوصف اللحظي: (الحالة، المتبقّي من الإدخال، المكدّس)
    for a in [""] + ([w[0]] if w else []):
        for p, g in D.get((q, a, st[:1]), []):
            yield (p, w[len(a):], g + st[1:])

def trace(word):
    start = ("q0", word, "Z")
    parent, todo = {start: None}, [start]
    for idn in todo:
        if idn[0] == "q2" and idn[1] == "":          # قبول: حالة نهائيّة وإدخالٌ مستهلَك
            path = []
            while idn:
                path.append(idn)
                idn = parent[idn]
            return path[::-1], len(parent)
        for nxt in moves(idn):                       # الأوصاف التي تلي هذا الوصف بالعلاقة |-
            if nxt not in parent:
                parent[nxt] = idn
                todo.append(nxt)
    return None, len(parent)

