# PF يقبل بالحالة النهائيّة f الكلمات التي عدد a فيها يساوي عدد b (المكدّس يحمل الفائض)
PF = {("q", "a", "Z"): [("q", "AZ")], ("q", "a", "A"): [("q", "AA")], ("q", "a", "B"): [("q", "")],
      ("q", "b", "Z"): [("q", "BZ")], ("q", "b", "B"): [("q", "BB")], ("q", "b", "A"): [("q", "")],
      ("q", "", "Z"): [("f", "Z")]}

def to_empty_stack(d, final):
    n = {**d, ("p0", "", "$"): [("q", "Z$")]}      # قاعٌ جديد $ لا يصل إليه PF أبداً
    for X in "ZAB$":
        n[("pe", "", X)] = [("pe", "")]            # حالة المحو تسحب أيّ رمز
        for f in final:
            n[(f, "", X)] = n.get((f, "", X), []) + [("pe", "")]   # من كلّ نهائيّة: امسح المكدّس
    return n

