# القواعد: S → a S b | a b  (لغة a^n b^n مع n ≥ 1)
GRAMMAR = {"S": [("a", "S", "b"), ("a", "b")]}

def pda_accepts(word):
    """PDA غير حتمي بحالةٍ واحدة: ينسخ إنتاجات CFG إلى المكدّس ويطابق الإدخال."""
    frontier = [(0, ("S",), [])]          # (موضع القراءة، المكدّس قمّته أوّلاً، السجلّ)
    while frontier:
        pos, stack, log = frontier.pop()
        if pos == len(word) and not stack:
            return log
        # كل رمزٍ في المكدّس يحتاج حرفاً من الإدخال، فنقلّم الفروع المستحيلة مبكراً
        if not stack or len(stack) > len(word) - pos:
            continue
        top, rest = stack[0], stack[1:]
        if top in GRAMMAR:                # حركة ε: استبدل المتغيّر بإنتاجٍ من إنتاجاته
            for rhs in GRAMMAR[top]:
                new = rhs + rest
                frontier.append((pos, new, log + [f"pop {top}, push {''.join(rhs)}  stack={''.join(new)}"]))
        elif pos < len(word) and word[pos] == top:   # قراءة: الحرف يطابق قمّة المكدّس
            frontier.append((pos + 1, rest, log + [f"read {top}  stack={''.join(rest)}"]))
    return None

