def conflicts(d):
    out = []
    for (q, a, X), moves in sorted(d.items()):
        if len(moves) > 1:
            out.append(f"({q},{a or 'eps'},{X}) has {len(moves)} moves")
        if a == "" and any((q, c, X) in d for c in "abc"):
            out.append(f"({q},eps,{X}) competes with a read move")
    return out

def machine(center):
    d = {("p", "", "Z"): [("f", "Z")]}
    for X in "ZAB":
        d[("q", "c" if center else "", X)] = [("p", X)]       # حرف المنتصف c، أو تخمينه بحركة eps
        for s in "ab":
            d[("q", s, X)] = [("q", s.upper() + X)]           # ندفع النصف الأوّل
    for s in "ab":
        d[("p", s, s.upper())] = [("p", "")]                  # مقابلة وسحب
    return d

def branching(d, w):                 # أكبر عدد حركاتٍ ممكنة في وصفٍ لحظيّ واحد أثناء التشغيل
    todo, seen, best, ok = [("q", 0, "Z")], set(), 0, False
    while todo:
        q, i, st = cfg = todo.pop()
        if cfg in seen:
            continue
        seen.add(cfg)
        opts = [(p, i + len(a), g + st[1:]) for a in (["", w[i]] if i < len(w) else [""]) for p, g in d.get((q, a, st[:1]), [])]
        best, ok, todo = max(best, len(opts)), ok or (i == len(w) and q == "f"), todo + opts
    return best, ok

for name, d, words in (("w c w^R", machine(True), ["abcba", "abcab"]), ("w w^R  ", machine(False), ["abba", "abab"])):
