def pbkdf2(pw, salt, rounds=1000):           # PBKDF2-HMAC-SHA256 كتلةٌ واحدة: تكرارٌ مكلف
    u = hmac.new(pw, salt + b"\x00\x00\x00\x01", hashlib.sha256).digest()
    t = int.from_bytes(u, "big")
    for _ in range(rounds - 1):
        u = hmac.new(pw, u, hashlib.sha256).digest()
        t ^= int.from_bytes(u, "big")
    return t.to_bytes(32, "big").hex()
def slow(pw, user): return pbkdf2(pw.encode(), f"salt-{user}".encode())
