def drop_eps(g):
    nullable = {A for A in g if () in g[A]}
    grow = True
    while grow:
        new = {A for A in g if any(all(x in nullable for x in r) for r in g[A])}
        grow, nullable = not new <= nullable, nullable | new
    out = {}
    for A in g:
        for r in g[A]:
            for keep in product((0, 1), repeat=len(r)):
                cand = tuple(x for x, k in zip(r, keep) if k or x not in nullable)
                if cand and cand not in out.setdefault(A, []):
                    out[A].append(cand)
    return out
def to_cnf(g):
    rules, count = [], 0
    for A in g:
        for r in g[A]:
            syms = [f"T_{x}" if x.islower() and len(r) > 1 else x for x in r]
            rules += [(f"T_{x}", (x,)) for x in r if x.islower() and len(r) > 1]
            head = A
            while len(syms) > 2:   # كسر القاعدة الطويلة إلى ثنائيّات بمتغيّراتٍ جديدة
                count += 1
                rules.append((head, (syms[0], f"N{count}")))
                head, syms = f"N{count}", syms[1:]
            rules.append((head, tuple(syms)))
    out = {}
    for A, r in rules:
        if r not in out.setdefault(A, []):
            out[A].append(r)
    return out
