def kind(g):
    ok = fixpoint(lambda s: {v for v in g for r in g[v] if all(c.islower() or c in s for c in r)})
    if "S" not in ok:
        return "empty", 0
    rules = {v: [r for r in g[v] if all(c.islower() or c in ok for c in r)] for v in ok}
    seen = fixpoint(lambda s: {"S"} | {c for u in s for r in rules[u] for c in r if c.isupper()})
    edge = {v: {c for r in rules[v] for c in r if c.isupper()} for v in seen}
    # دورة: متغيّر يصل إلى نفسه بمسار طوله 1 أو أكثر
    loop = any(v in fixpoint(lambda s: edge[v] | {c for u in s for c in edge[u]}) for v in seen)
    return ("infinite" if loop else "finite"), len(seen)

def count(g, n):   # كلمات طولها <= n (القواعد بلا ε فلا يقصر النموذج الجملي)
    seen, out, todo = set(), set(), ["S"]
    while todo:
        f = todo.pop()
        if f in seen or len(f) > n:
            continue
        seen.add(f)
        i = next((k for k, c in enumerate(f) if c.isupper()), None)
        if i is None:
            out.add(f)
        else:
            todo.extend(f[:i] + r + f[i + 1:] for r in g[f[i]])
    return len(out)

