def cyk(w):
    n = len(w)
    T = {(i, 1): {A for A, r in RULES if r == w[i]} for i in range(n)}   # الطول 1: القواعد الطرفيّة
    BP = {}
    for L in range(2, n + 1):
        for i in range(n - L + 1):
            T[i, L] = set()
            for A, r in RULES:
                for k in range(1, L):   # نقسم المجال [i, i+L) عند كل موضع k
                    if len(r) == 2 and r[0] in T[i, k] and r[1] in T[i + k, L - k]:
                        T[i, L].add(A)
                        BP.setdefault((i, L, A), (r, k))
    return T, BP

def tree(w, BP, A, i, L):
    if L == 1:
        return f"{A}({w[i]})"
    r, k = BP[i, L, A]
    return f"{A}[{tree(w, BP, r[0], i, k)} {tree(w, BP, r[1], i + k, L - k)}]"

